# Called by 12_compare_r5_r7_regressions.R with stats and plans in memory.
fmt <- function(x, digits = 3) formatC(x, format = "f", digits = digits)
stars <- function(p) {
  case_when(p < .01 ~ "$^{***}$", p < .05 ~ "$^{**}$",
            p < .10 ~ "$^{*}$", TRUE ~ "")
}

row <- function(label, values) {
  paste0(label, " & ", paste(values, collapse = " & "), " \\\\")
}
lines <- c(
  "% Generated by code/12_compare_r5_r7_regressions.R",
  "\\begin{table}[!htbp]\\centering",
  "\\caption{Employment IV estimates: Selected R5 and R5--R7 pooling}",
  "\\label{tab:r5r7compare}",
  "\\linespread{1}\\selectfont",
  "\\begin{threeparttable}\\small",
  "\\begin{tabular}{lrrrr}\\toprule",
  " & \\multicolumn{2}{c}{Non-Addis} &",
  "\\multicolumn{2}{c}{Also excluding Amhara} \\\\",
  "\\cmidrule(lr){2-3}\\cmidrule(lr){4-5}",
  " & Salary & Wage & Salary & Wage \\\\",
  "\\midrule"
)
for (panel_id in c("A", "B")) {
  display_panel <- panel_id
  s <- stats |> filter(panel == panel_id)
  title <- switch(panel_id,
    A = "Round 5: older cohort",
    B = "Rounds 5 and 7: both cohorts (exploratory)"
  )
  lines <- c(lines,
    paste0("\\multicolumn{5}{l}{\\textbf{Panel ", display_panel,
           ": ", title, "}} \\\\") ,
    row("$MTIuse$", paste0(fmt(s$iv_beta), stars(s$iv_p))),
    row("", paste0("(", fmt(s$iv_se), ")")),
    row("Excluded-instrument $F$", fmt(s$first_stage_F, 2)),
    row("Controls", rep("Yes", 4)),
    row("Round dummy", rep(ifelse(panel_id == "A", "No", "Yes"), 4)),
    row("Cohort dummy", rep(ifelse(panel_id == "A", "No", "Yes"), 4)),
    row("Observations", as.character(s$n)),
    "\\midrule"
  )
}
lines <- c(lines,
  "\\bottomrule\\end{tabular}",
  "\\begin{tablenotes}\\scriptsize",
  "\\item Notes: 2SLS instruments frozen R5 MTI with historical $E_{is}$.",
  "Panel A re-estimates R5 under the current sample exclusions.",
  "Salary=13; combined farm/nonfarm wage=5--7/12/19.",
  "R5 uses its first-ranked activity; R7 uses its annual main activity.",
  "R5 non-interviews, unknown first types and other work are excluded.",
  "Controls match Table 2. R7 household size, wealth, housing, durables",
  "and electricity are contemporaneous, with original index definitions;",
  "R5 resources retain their original R3 timing. Food situation is R3.",
  "\\item Panel A uses selected R5 observations without the score gate.",
  "Panel B applies the historical R4 nonzero/nonmissing score gate to OC",
  "in both rounds; YC has no score gate. Panel B includes round and cohort.",
  "R7 is in person only. Complete cases are selected per outcome.",
  "R5 YC employment is unavailable, so Panel B adds YC only in R7.",
  "Panel B is exploratory: YC completed-primary MTI remains unvalidated.",
  "Pooling assumes a common MTI slope; no participant fixed effects.",
  "\\item Conventional standard errors in parentheses. Stars use",
  "conventional inference: *** $p<0.01$, ** $p<0.05$, * $p<0.10$.",
  "Regional inference diagnostics are retained separately.",
  "\\end{tablenotes}\\end{threeparttable}\\end{table}"
)
file <- "output/tables/table_r5_r7_comparison.tex"
writeLines(lines, file)
mirror_output(file, "tables")
